add('01  CurtainDrive V3.1｜交付状态',P('本轮完成离线工程与制造资料核验。样机电气、抗扰、温升、转矩、停止距离和完整固件运行验收尚未执行。采用当前磁盘 V3，完整备份后在独立副本修改；源工程及未保存的编辑器状态未覆盖。'),P('最终 PCB SHA-256：\n'+h[:32]+'\n'+h[32:]),T(['项目','基线 V3','最终 V3.1'],[['轨迹 / 过孔','2284 / 475','2107 / 489（新增14个有效地桥）'],['严格微短段 / 阈值边界','240 / 3','145 / 3；原243项全部建账'],['非标准整数角度段','600','537；逐项接入/侧接/绕障例外'],['器件 / 电气焊盘','151 / 469','151 / 469，脚网、型号、数值不变'],['制造资料','旧版本保留','Gerber、孔图、BOM、CPL重新生成']],[.35,.28,.37]),P('固定 ESP32、全部外接端子、三个电源模块、J16/J17/J19、板框、天线禁布区、六孔及外壳/按钮仓/开口/支撑。只交换同面 C35/R57 的位置并重布局部连接；没有增加器件、测试点或改变功能拓扑。'),P('主要限制：0.05Ω供电目标未达到；若干既有换层地桥距离仍偏长；热源合并模型与未知线束/接触/材料需要样机校准。未承诺绝对最优或量产性能。'))
add('02  整机原理与模块职责',T(['模块 / 位号','实际作用、源与返回','失效 / 边界'],[['GST120A24-P1M','24V/5A电源分配至控制PCB、板外驱动电源和K1线圈。','电机相电流、驱动输入电流与PCB控制电流分开。'],['CL1-42C +42CME04D','相线及编码器直接连接驱动器，延长线1.5m。','相线、驱动负极不得通过PCB信号地承担功率回流。'],['U1 / U11 / U33','U1产生5V；U11/U33分别产生6.5V限位触点电源。','CASE散热铜浮置且彼此分离，不能连GND。'],['四路SS-01GL2','使用COM/NC，约7.1mA/750Ω；两只备用不接入控制。','LO/RO阻止OPEN；LC/RC阻止CLOSE；允许退离。'],['U34～U40 / U42 / U45','滤波极性、方向联锁、授权锁存、脉冲门控和看门狗。','故障恢复本身不重新授权。'],['ESP32-S3 DevKitC-1 N8R8 v1.1','网页控制、配对、行程校准与传感器；固件未编写。','不能以离线逻辑模型替代应用状态机和通信租约。'],['SEN0228 / SET / BZ1','100kHzI2C光照、24V红灯自复位SET、内部5V有源蜂鸣器。','实际线长、SET灯电流/后端、USB线缆仍待确认。']],[.25,.44,.31]),P('五张理解表（功能块、电源/电流、信号/边沿、事件/故障、机械/外接线）在任何布局修改前完成。完整表、原始手册文件和来源哈希位于 evidence/baseline。光耦逻辑与系统地共用，不能称为安全电气隔离。'))
add('03  电源、电流与电压预算',P('控制路径 J1→F1→D1/D8/C7→U1；MCU路径 U1.3→D9→J19→U2.21，返回 U2.22→U1.2。保留保护和全部原有电容支路、J19电源断开功能。普通USB供电时拔开J19，保持板载与USB两路供电互斥。'),T(['20℃ / 35µm铜筛查','V3','V3.1'],[['中心线前向路径电阻',fnum(base['centreline_forward_ohm_20C'])+'Ω',fnum(new['centreline_forward_ohm_20C'])+'Ω'],['铜覆盖并集电阻（0.04mm网格）',fnum(sheet0)+'Ω',fnum(sheet1)+'Ω'],['GND返回（0.15mm网格）',fnum(base['sheet_ground_ohm_20C'],4)+'Ω',fnum(new['sheet_ground_ohm_20C'],4)+'Ω']],[.52,.24,.24]),P(f'独立铜面方法前向降低约{pct:.1f}%。两种方法具有不同偏差；中心线分段与理想焊盘接触会影响数值，铜并集网格包含对角/细颈离散误差，不能写成实测阻抗。0.2mm地栅格不能解析细颈，记录为RASTER_UNRESOLVED；实际铜连接由独立多边形及原生DRC确认。'),T(['供电场景 / 80℃铜','U2.21预算','剩余接触/纹波/瞬态余量'],[['0.5A、U1下界4.70V、D9筛查0.55V','3.993V','约0.313V，相对3.68V LDO筛查'],['0.8A、同样组合不利下界','3.899V','约−0.011V，相对3.91V；不保证']],[.49,.20,.31]),P('SGM2212为v1.1 DevKit实际LDO。手册压差定义在95%标称输出，不能当作精确3.3V稳压保证。模块精度和负载调整各−3%相加仅为敏感性，可能重复计入；二极管温度、跳帽/母座接触和瞬态须实测。0.5A为本轮核验包络，尚未验证实际峰值。'))
add('04  监督、器件规格与心跳契约',T(['关系','已核实的电气意图','需要实物/固件完成'],[['U41 / U44','3.3V与5V监督；U41阈值3.08V±2%，最低3.0184V；约200ms释放。','欠压波形、释放和局部3.3V最低值。'],['U45.3 EN','DevKit EN通过MCU_RESET_N控制看门狗使能；EN是输入。','EN复位时ENOUT快速禁止运动。'],['U45.6 WDI','GPIO47→R59→WDI；有效下降沿喂狗。','高电平保持不喂狗；控制任务停更必须停止下降沿。'],['U45.7/8 WDT_OK','WDO和ENOUT为允许组合的开漏输出，上拉后经U39清除U40。','170～230ms超时/启动延时；不会直接复位ESP32。'],['U40 CLR / CLK','D与PRE为高；故障清CLR，GPIO6经R5进入ARM_CLK，R35下拉。','健康恢复且GPIO6持续HIGH不再ARM，需新LOW→HIGH。'],['Q1～Q6 / 触点','已有栅极串阻/下拉、默认禁止、保持力路径和SET低侧驱动保留。','报警极性/驱动ENA脱机语义、CTR温度和SET灯电流。']],[.25,.44,.31]),P('手册以实际MPN及封装锁定；工作范围和门限使用推荐条件，不借绝对最大值证明正常可用。6.5V转换模块约1.4%轻载，低于厂家10～100%性能测试范围，电压、效率和纹波待实物校准。输入TVS钳位也不能替代异常电源瞬态实测。'),P('软件契约：GPIO47应由健康控制任务维护，≤50ms更新/≤100ms有效下降沿；应用停更、通信租约到期或状态异常时停喂狗。独立ISR/RMT自动心跳不得掩盖应用停更。TI TPS3431手册及锁定SHA在来源目录；尚未有运行固件。'))
add('05  启动、停止与故障恢复',T(['事件','脉冲 / 授权行为','保持力与恢复'],[['上电 / 欠压','监督未就绪时禁止；恢复需新ARM边沿。','健康驱动供电后按固件低速验证。'],['普通STOP','经硬件联锁禁止STEP并清授权。','ESTOP和POWER健康时保持力保留。'],['当前方向限位NC断开','OPEN方向LO/RO；CLOSE方向LC/RC清授权。','反方向限位断开允许退离，不能称全方向断线监控。'],['驱动ALM','按J17/驱动PA配置的实际极性清授权。','驱动内部故障时不能保证转矩。'],['EN复位 / WDI HIGH保持 / 心跳丢失','ENOUT独立禁止；无有效下降沿到超时后清RUN。','WDT不复位ESP；恢复仍需重新ARM。'],['急停','板外K1切驱动正电源；U24仅检测线圈命令。','掉电不能保证保持力；触点焊死/断开无反馈。'],['健康恢复但GPIO6仍HIGH','U40不会自动重锁存授权。','先LOW，再新的有效HIGH边沿。']],[.31,.39,.30]),P('16384个14输入静态向量、22个含实际GPIO6的方向/故障状态序列及170/200/230ms独立EN/WDI边沿模型全部通过。这些是离线事件模型，不覆盖传播延迟、触点弹跳、模拟欠压、转矩与位置。'),P('STEP契约≤100kHz、HIGH/LOW≥5µs；DIR设置≥10µs、ENA稳定≥5ms。230ms窗口在100kHz可容纳23000脉冲，不能称立即停止或认证安全功能。异步清除可能截短脉冲；位置失效时需重新回零/校准。'))
add('06  候选布局比较与淘汰理由',I('candidate_placement','A/B/C同尺度布局提案。B/C未通过硬门槛，不能把几何下界当作完成布线。'),T(['候选','局部工程评估','结果'],[['A 保留主要布局','内部原位置保留；C35/R57同面同方向交换并比较完整控制链。','采用，逐组真实铜核验。'],['B 看门狗外围迁移','U45/C35/R57/R58/R60移至133,88附近；42项院落/焊盘冲突，CASE占用约14.8mm²。','装配、间距和散热门槛淘汰。'],['C 监督/联锁联合迁移','有限0.5mm网格扫掠U39/C29；最少冲突位置仍碰C25和异网铜。','该候选族0合法站点，未采用。']],[.25,.52,.23]),P('RESET、两段心跳、POR、POWER_OK、ARM、RUN清除/反馈、STEP、DIR、HOLD及去耦同时列入CSV比较。C的几何下界虽缩短RUN_CLR等，PUL_GATED变长且装配冲突未解决；不能仅按总线长选C。本轮不证明其它所有联合布局均不可行。'))
add('07  第一组：电源与实际GND',I('comparison_power','同尺度底面，黄色高亮MCU供电相关铜；保护返回通道优先于整体加宽。'),P('最终主干仅在合法空间加宽，局部保留0.3～0.6mm逃线；J19固定导致较长通路，0.8～1.0mm目标未能铺满。中心线路径约112.42→114.00mm，电阻仍下降，说明线长不能替代供电截面和返回评估。'),P('曾完成更激进加宽试验，中心线筛查降至约0.169Ω，但固定空间采样发现RESET/ARM/I2C地参考损失，已淘汰。最终采用保护基线关键网络附近GND的方法；该失败方案和原因保留在工作备份及evidence/rejected_power_reference.json。'),P('新增14个地桥在两面都接入实际GND且回到J1.2；保留U1/U11/U33 CASE直接散热连接、输入保护和电容侧接。DIR附近0.8mm电源段退回0.4mm，恢复远端地角。铜图百分比不代替这项检查。'))
