add('08  第二组：C35、复位与授权',I('comparison_watchdog','仅C35/R57交换；U45、R58/R60保留位置和装配面。黄色为电源与GND，信号红色。'),T(['局部量','V3','V3.1'],[['U45.1→C35.1外露铜路径',fnum(cap0['trace_length_mm'])+'mm',fnum(cap1['trace_length_mm'])+'mm'],['C26→U36外露铜路径','0.602mm','0.602mm（保持）'],['C30→U40外露铜路径','0.775mm','0.775mm（保持）'],['RUN_CLR最近地最坏间隙','1.792mm','1.517mm；筛查值']],[.53,.235,.235]),P('外露铜路径扣除理想焊盘内部连接，不能与器件中心距离混用。C35电源侧接、CWD/R57、上拉R58、下拉R60及U45暴露焊盘GND均逐项复核。'),P('RESET局部新逃线处最近顶面GND约0.291→0.354mm，增加0.063mm；对面GND和全网最坏间隙不变。以U45.4为根的短地铜延伸维持连接。明确记录这处局部变化，未将最近距离统计写成零退化或EMC证明。'))
add('09  运动输出与外部接口',T(['完整通路','处理和连接核对','物理限制'],[['STEP','MCU_STEP→U37→STEP_LATCHED→U39→PUL_GATED→Q1→PUL−。','门控拓扑保留；任何异步截脉冲需位置恢复策略。'],['DIR / ENA / HOLD','Q2方向；Q3控制脱机；Q5在健康供电/急停条件下保留保持。','J16/J17服务跳帽固定，实际极性需驱动调试。'],['四限位','COM/NC返回经750Ω与光耦/RC/逻辑；触点供电6.5V。','每路约0.037W串阻功耗；旧33Ω发热支路不再存在。'],['I2C光照','U30 VCC/GND/SDA/SCL；Gravity端SDA/SCL/GND/VCC，线束必须交叉对应；D15与100Ω不变。','100kHz，实际电容/上升沿/VOL/抗扰验收；未知米数不保证。'],['SET / 蜂鸣器','J18:24V_COM、NO返回、灯A、灯K；NC空置绝缘。BZ1 KLJ-9650-5Y，壳内5V30mA。','灯20/50mA为建模假定；不代表所购按钮实测。']],[.23,.47,.30]),P('第三组运动输出通过核对后保留原几何，避免仅为了轻微整齐而改动快速边沿。第四组只清理FUNC_BTN_RET的局部路径。I2C试验的微小缩短导致地参考变化，最终维持原路，不做蛇形等长。'),P('外部PUL/DIR/ENA与各自共阳极5V返回成对布置；限位、I2C及面板线远离电机相线。驱动负极独立回电源分配点，不借PCB信号GND承担电机电源回流。'))
add('10  全板清理、角度与丝印',T(['原243项处置','数量','依据'],[[k,str(v),{'保留':'完整截面/原生接入','冗余覆盖删除':'完整包在其它同网显式铜内','共线合并':'整数区间铜覆盖并集相同','局部重布替换':'电源/逻辑/接口阶段核验','原生接入重建':'过孔中心接入规则保留'}[k]] for k,v in micro['original_action_counts'].items()],[.36,.12,.52]),P('严格小于0.15mm为240项，恰等于阈值3项；旧241是浮点边界口径。CSV逐项记录原UUID、网络、层、整数端点、宽度、用途、支路、处置、新UUID与检查。铜接入不存在“一删飞线为零就正确”的推断。'),P('最终148项：128焊盘/过孔接入、7宽度过渡、13足宽短拐角/侧接。537项整数非标准角度在JSON逐项记录接入对象、偏离量与附近异网间距；密集原有通道保留必要例外，不声称全部主干几何已绝对最优。零长度和完全重复段为零。'),I('silk_actual_positions','200处可见原生丝印文本：139个0°、61个90°（模180）。图采用实际位置/角度；完整大图在figures。'),P('C35/R57位号已跟随局部移位靠近元件。电压、极性和功能标注保留，原生丝印与焊盘检查通过；实际手工观察和器件遮挡仍须按装配图及样机核验。'))
add('11  顶面前后同尺度总览',I('comparison_top','铜形状来自实际填充，坐标和尺度一致；缺口、支路和过孔保持可对照。'),I('PCB_F_Cu','最终顶面独立大图；本报告缩略图不替代原生PCB/高分辨率铜图。'),P('CASE占据模块附近通道；优化同时保留GND实际连接。功能相关线采用已有清楚通道，对必要焊盘接入、跨层与支路不强制拉直。全板未整体拆线或交给自动布线代替比较。'))
add('12  底面前后同尺度总览',I('comparison_bottom','底层已有密集逻辑、阻容及驱动小器件；固定装配面后局部处理。'),I('PCB_B_Cu','最终底面图使用同一KiCad坐标投影，未镜像；制造CPL单独检查底面旋转和层归属。'),P('重复显式铜删除和共线合并仅改变必要对象集合；全部中途接入、焊盘与过孔重新独立检测。器件没有换面，CPL中C35/R57坐标随PCB更新。'))
add('13  三轮PCB、两轮一致性证据',T(['独立轮次','方法','最终结果'],[['PCB第1轮','原生DRC、未连接、脚网/工艺及固定对象','违规0，未连接0，针网/固定差异0。'],['PCB第2轮','Shapely实际铜/焊盘/孔槽/镀通；支路与回流','469针连接，短路0、开路0、孤立导体0；CASE逐面达到基线。'],['PCB第3轮','整机故障/恢复、装配工具、热/支撑/CAD','离线模型完成，动态实物项目未执行。'],['一致性1','11张SCH非线对象与线覆盖并集；XML网表与PCB','元件、针网、封装及数量差异0；库仅改命名。'],['一致性2','Gerbonara解析真实Gerber/Excellon/BOM/CPL','双面铜±3µm外差0；596孔、130SMT坐标一致。']],[.19,.43,.38]),P('原理图另完成三轮：配置ERC0；重新启用类别后31项绘图风格警告逐项处置（10四向共点、21单处全局标签）；实际器件/针网/监督契约核实；独立故障与边沿序列复核。没有把被忽略类别伪装成不存在。'),P('Gerber多边形量化对称差顶/底约0.236/0.392mm²，超过3µm的多余或缺失面积均为0。590镀孔+6非镀孔逐孔匹配，工具/坐标按0.001mm输出半量子核验。130SMT和21手工插件/模块分列；库存贴装库pin1/极性旋转须在下单预览验收。'),P('模型中的静态真值、源哈希和文件导出成功均不等于实物电气/EMC/停机性能。'))
